323	  queryForm.materialName = node.materialName || "";
324	  queryForm.lot = node.batchNo;
325	  setSelectedMaterial(node.materialName, node.materialId);
326	  lineageQuery.value = query;
327	  hasSearched.value = true;
328	  showSummary.value = true;
329	  void refreshSummary(query, node);
