 1	import type {
 2	  BatchLineageLotOption,
 3	  BatchLineageMaterialOption,
 4	} from "./BatchLineageSearch.types";
 5	
 6	/** 兼容列表接口直接返回数组或分页对象的两种格式。 */
 7	export function getListData(data: any): any[] {
 8	  if (Array.isArray(data)) return data;
 9	  return data?.list || data?.rows || [];
10	}
11	
12	/** 将物料接口返回值统一为自动完成组件可用的数据格式。 */
13	export function createMaterialOptions(data: any[] = []) {
14	  const materialIds = new Set<number>();
15	
16	  return data.reduce<BatchLineageMaterialOption[]>((options, item) => {
17	    const maId = Number(item?.maId ?? item?.materialId);
18	    const materialName = item?.maName ?? item?.materialName ?? item?.label;
19	    if (!maId || !materialName || materialIds.has(maId)) return options;
20	
21	    materialIds.add(maId);
22	    options.push({ label: materialName, value: materialName, maId });
23	    return options;
24	  }, []);
25	}
26	
27	/** 将批次接口返回值统一为下拉框可用的数据格式。 */
28	export function createLotOptions(data: any[] = []) {
29	  const lots = new Set<string>();
30	
31	  return data.reduce<BatchLineageLotOption[]>((options, item) => {
32	    const lot = String(
33	      typeof item === "string" ? item : item?.batch ?? item?.lot ?? "",
34	    );
35	    if (!lot || lots.has(lot)) return options;
36	
37	    lots.add(lot);
38	    options.push({ label: lot, value: lot });
39	    return options;
40	  }, []);
41	}

