 17	
 18	/** 批次血缘单位展示优先级：单位名称、单位简称、单位、单位编码。 */
 19	function getBatchLineageUnit(data?: {
 20	  unitName?: string | null;
 21	  stuName?: string | null;
 22	  unit?: string | null;
 23	  stu?: string | null;
 24	}) {
 25	  return (
 26	    data?.unitName || data?.stuName || data?.unit || data?.stu || undefined
 27	  );
 28	}
 29	
 30	/** 将节点单位统一写入 unit，供图谱展示层直接使用。 */
 31	function normalizeBatchLineageNode(node: BatchLineageNode): BatchLineageNode {
 32	  return {
 33	    ...node,
 34	    unit: getBatchLineageUnit(node),
 35	  };
 36	}
 37	
 38	/** 将详情单位统一写入 unit，供批次摘要直接使用。 */
 39	function normalizeBatchLineageDetail(
 40	  detail?: BatchLineageDetail,
 41	): BatchLineageDetail | undefined {
 42	  if (!detail) return detail;
 43	
 44	  return {
 45	    ...detail,
 46	    unit: getBatchLineageUnit(detail),
 47	  };
 48	}
 49	
 50	/** 统一图谱及懒加载接口的节点单位字段。 */
 51	function normalizeBatchLineageResponse(
 52	  response: BatchLineageResponse,
 53	): BatchLineageResponse {
 54	  return {
 55	    ...response,
 56	    data: response.data
 57	      ? {
 58	          ...response.data,
 59	          nodes: response.data.nodes?.map(normalizeBatchLineageNode),
 60	        }
 61	      : response.data,
 62	  };
 63	}
 64	
 65	/**
 66	 * 批次血缘图谱查询接口。
 67	 */
 68	export async function queryBatchLineage(
