602	export function getBranchElementIds(
603	  edges: EdgeData[],
604	  nodeId: string,
605	  direction: BranchDirection,
606	) {
607	  const nodeIds = new Set([nodeId]);
608	  const edgeIds = new Set<string>();
609	  const pendingNodeIds = [nodeId];
610	
611	  while (pendingNodeIds.length) {
612	    const currentNodeId = pendingNodeIds.shift() as string;
613	    const relatedEdges = edges.filter((edge) =>
614	      direction === "upstream"
615	        ? edge.target === currentNodeId
616	        : edge.source === currentNodeId,
617	    );
618	
619	    relatedEdges.forEach((edge) => {
620	      const nextNodeId = String(
621	        direction === "upstream" ? edge.source : edge.target,
622	      );
623	      edgeIds.add(String(edge.id));
624	
625	      if (!nodeIds.has(nextNodeId)) {
626	        nodeIds.add(nextNodeId);
627	        pendingNodeIds.push(nextNodeId);
628	      }
629	    });
630	  }
631	
632	  nodeIds.delete(nodeId);
633	  return [...nodeIds, ...edgeIds];
634	}
