 7	/** 批次血缘中间摘要及检验结果字典加载。 */
 8	export function useBatchLineageSummary() {
 9	  const {
10	    getDictionaryList: getCheckResultDictionary,
11	    dictionaryList: checkResultDictionary,
12	  } = useDictionary();
13	  let dictionaryRequest: Promise<void> | undefined;
14	
15	  /** 仅首次加载检验结果字典，避免每次查询摘要都重复请求。 */
16	  const loadCheckResultDictionary = () => {
17	    if (!dictionaryRequest) {
18	      dictionaryRequest = getCheckResultDictionary("laboratoryResult");
19	    }
20	    return dictionaryRequest;
21	  };
22	
23	  /** 查询详情接口并生成页面中间摘要。 */
24	  const refreshSummary = async (
25	    query: BatchLineageRequest,
26	    node?: LineageNodeMeta,
27	  ) => {
28	    await loadCheckResultDictionary();
29	    return fetchBatchLineageSummary(
30	      query,
31	      node,
32	      checkResultDictionary.value,
33	    );
34	  };
35	
36	  onMounted(() => {
37	    void loadCheckResultDictionary();
38	  });
39	
40	  return { refreshSummary };
41	}

