 12	/** 将数量和单位转换为摘要区域使用的文本。 */
 13	function formatQuantity(value?: number | string | null, unit?: string | null) {
 14	  if (value === undefined || value === null || value === "") return "--";
 15	  return `${value}${unit ? ` ${unit}` : ""}`;
 16	}
 17	
 18	/** 根据检验结果字典，将后端字典值转换为页面展示文本。 */
 19	export function getCheckResultText(
 20	  checkResult: string | null | undefined,
 21	  dictionaryOptions: BatchLineageDictionaryOption[],
 22	) {
 23	  if (!checkResult) return "未发起";
 24	
 25	  return (
 26	    dictionaryOptions.find((item) => item.valueKeyName == checkResult)
 27	      ?.keyValue || checkResult
 28	  );
 29	}
 30	
 31	/** 根据检验结果展示文本获取节点与摘要共用的状态颜色。 */
 32	export function getCheckResultColor(status?: string | null) {
 33	  if (status === "未发起") return "#8c8c8c";
 34	  if (status?.includes("不合格")) return "#ff4d4f";
 35	  if (status?.includes("让步")) return "#faad14";
 36	  return "#52c41a";
 37	}
 38	
 39	/** 根据检验结果展示文本获取节点与摘要共用的标签样式。 */
 40	export function getCheckResultTagStyle(status?: string | null) {
 41	  const color = getCheckResultColor(status);
 42	  if (status === "未发起") {
 43	    return {
 44	      backgroundColor: "rgba(0, 0, 0, 0.02)",
 45	      borderColor: "rgba(0, 0, 0, 0.15)",
 46	      color: "rgba(0, 0, 0, 0.88)",
 47	    };
 48	  }
 49	  if (status?.includes("不合格")) {
 50	    return { backgroundColor: "#FFF1F0", borderColor: color, color };
 51	  }
 52	  if (status?.includes("让步")) {
 53	    return { backgroundColor: "#FFF7E6", borderColor: color, color };
 54	  }
 55	
 56	  return { backgroundColor: "#F6FFED", borderColor: color, color };
 57	}
